def transform(g):
    from collections import deque
    h,w=len(g),len(g[0])
    fives=[(r,c) for r in range(h) for c in range(w) if g[r][c]==5]
    def has_nbr(f):
        r,c=f
        return any(g[r+dr][c+dc]!=0 for dr,dc in((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<h and 0<=c+dc<w)
    obj5=[f for f in fives if has_nbr(f)][0]
    marker=[f for f in fives if f!=obj5][0]
    seen={obj5}; dq=deque([obj5]); cells=[]
    while dq:
        r,c=dq.popleft(); cells.append((r,c))
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and g[rr][cc]!=0 and (rr,cc) not in seen:
                    seen.add((rr,cc)); dq.append((rr,cc))
    dr,dc=marker[0]-obj5[0], marker[1]-obj5[1]
    out=[row[:] for row in g]
    for r,c in cells:
        rr,cc=r+dr,c+dc
        if 0<=rr<h and 0<=cc<w:
            out[rr][cc]=0 if g[r][c]==5 else g[r][c]
    return out

